	$(document).ready(function() {
		var popCtrPrev = $(".ytb_control .ytb_prev");
		var popCtrNext = $(".ytb_control .ytb_next");
		
		//팝업 일시정지
		$(".ytb_control .ytb_pause").on("click", function() {
			$(".m_youtube > .ytb_list").slick("slickPause");
			$(".ytb_control .ytb_pause").css({"display":"none"});
			$(".ytb_control .ytb_play").css({"display":"inline-block"});
			$(".ytb_play").focus();			
		});
		//팝업 재생
		$(".ytb_control .ytb_play").on("click", function() {
			$(".m_youtube > .ytb_list").slick("slickPlay");
			$(".ytb_control .ytb_play").css({"display":"none"});
			$(".ytb_control .ytb_pause").css({"display":"inline-block"});
			$(".ytb_pause").focus();
		});  
		
		$('.m_youtube > .ytb_list').slick({
			slidesToShow : 1,
			autoplay : true,
			autoplaySpeed : 3000,
			arrows : true,
			fade: true,
			dots: true,
			appendDots: $('.ytb_slide_dot'),
			prevArrow : popCtrPrev,
			nextArrow : popCtrNext,
			pauseOnDotsHover : true,
		}); 
	});
	
